#Requires -Version 5.1
# Canonical task-specific runtime. The GitHub copy is generated by shared_guidance.py.
function Get-CourseStaticHash($Value) {
    $bytes=[Text.Encoding]::UTF8.GetBytes(($Value|ConvertTo-Json -Depth 12 -Compress))
    $hash=[Security.Cryptography.SHA256]::Create()
    try{return ([BitConverter]::ToString($hash.ComputeHash($bytes))).Replace('-','').ToLowerInvariant()}finally{$hash.Dispose()}
}
function Invoke-CourseStaticProbe([string]$Cli,[string[]]$Arguments,[string]$Root,[int]$Timeout=20) {
    $result=Invoke-SetupNative $Cli $Arguments $Timeout $Root
    if($result.ExitCode -ne 0){throw 'STATIC_RUNTIME_PROBE_FAILED: restore the recorded engine or image; no toolchain substitution.'}
    $parsed=$(if($result.Stdout){$result.Stdout}else{$result.Output})|ConvertFrom-Json
    # Windows PowerShell 5.1 emits a JSON root array as one pipeline object.
    foreach($item in $parsed){Write-Output $item}
}
function Assert-CourseStaticPodmanBinding($Machine,$Connection) {
    # Keep the selected-machine check self-contained for older recorded preparation packages.
    $expectedName=if($Machine.Rootful){$Machine.Name+'-root'}else{$Machine.Name}
    $expectedUser=if($Machine.Rootful){'root'}else{[string]$Machine.SSHConfig.RemoteUsername}
    $identity=[string]$Machine.SSHConfig.IdentityPath;$port=[int]$Machine.SSHConfig.Port
    if($expectedUser -notmatch '^[a-z_][a-z0-9_-]*$' -or $port -lt 1 -or $port -gt 65535 -or -not [IO.Path]::IsPathRooted($identity)){throw 'STATIC_MACHINE_METADATA_INVALID'}
    if($Connection.Name -cne $expectedName -or $Connection.IsMachine -ne $true -or -not $Connection.Identity -or [IO.Path]::GetFullPath($Connection.Identity) -ine [IO.Path]::GetFullPath($identity)){throw 'STATIC_CONNECTION_IDENTITY_MISMATCH'}
    $uri=[uri]$Connection.URI
    $socket=if($Machine.Rootful){$uri.AbsolutePath -ceq '/run/podman/podman.sock'}else{$uri.AbsolutePath -cmatch '^/run/user/[0-9]+/podman/podman\.sock$'}
    if($uri.Scheme -cne 'ssh' -or $uri.Host -cne '127.0.0.1' -or $uri.Port -ne $port -or $uri.UserInfo -cne $expectedUser -or -not $socket -or $uri.Query -or $uri.Fragment){throw 'STATIC_LOCAL_CONNECTION_REQUIRED'}
    Assert-CoursePlainPath $identity
}
function Get-CourseStaticPodmanConnection([string]$Cli,[string]$Connection,[string]$Root) {
    if($Connection -notmatch '^podman-machine-[a-zA-Z0-9_-]+$'){throw 'PODMAN_LOCAL_CONNECTION_REQUIRED'}
    $machineName=$Connection -replace '-root$',''
    $machine=@(Invoke-CourseStaticProbe $Cli @('machine','inspect',$machineName) $Root)[0]
    if($machine.Name -cne $machineName){throw 'STATIC_MACHINE_BINDING_CHANGED'}
    $connections=@(Invoke-CourseStaticProbe $Cli @('system','connection','list','--format','json') $Root)
    $selected=@($connections|Where-Object {$_.Name -ceq $Connection})
    if($selected.Count -ne 1){throw 'STATIC_CONNECTION_BINDING_REQUIRED'}
    Assert-CourseStaticPodmanBinding $machine $selected[0]
    $fingerprint=Get-CourseStaticHash ([ordered]@{machine=$machineName;rootful=[bool]$machine.Rootful;uri=$selected[0].URI;identity=$selected[0].Identity})
    return @{machine=$machine;fingerprint=$fingerprint}
}
function Get-CourseStaticRuntime {
    param([string]$Root,[string]$ExecutionRoot,[switch]$Start,$PriorContext,[string]$OperationId)
    $helpers=Join-Path $ExecutionRoot 'scripts'
    . (Join-Path $helpers 'Course-ProjectRoot.ps1')
    . (Join-Path $helpers 'Course-Native.ps1')
    $Root=Resolve-CourseProjectRoot $Root
    $p=Read-CourseJson (Join-Path $Root '.ai-coding/project.json')
    if($p.containerRuntime -notin @('docker','podman') -or -not $p.image -or $p.toolchain.imageDigest -cnotmatch '^sha256:[a-f0-9]{64}$'){throw 'PROJECT_TOOLCHAIN_BINDING_REQUIRED'}
    if($p.containerRuntime -eq 'podman'){. (Join-Path $helpers 'Course-Podman.ps1')}else{. (Join-Path $helpers 'Course-Docker.ps1')}
    if(Get-Command Assert-CourseInstallationActive -ErrorAction SilentlyContinue){Assert-CourseInstallationActive $Root}
    $lease=$null
    if(Get-Command Enter-CourseOperation -ErrorAction SilentlyContinue){$lease=Enter-CourseOperation $Root 'StaticPublish'}
    try {
        $connection=$null
        if($p.containerRuntime -eq 'podman'){
            $cli=(Get-PodmanPaths).Cli
            if(-not $cli){throw 'PODMAN_CLI_UNAVAILABLE'}
            $prefix=@('--connection',$p.connection)
            $connection=Get-CourseStaticPodmanConnection $cli $p.connection $Root
        } else {
            $paths=Get-SetupDockerPaths;$cli=$paths.Cli
            if(-not $cli){throw 'DOCKER_CLI_UNAVAILABLE'}
            $prefix=@('--host','npipe:////./pipe/dockerDesktopLinuxEngine')
        }
        Assert-CoursePlainPath $cli
        if(-not [IO.Path]::IsPathRooted($cli) -or -not(Test-Path -LiteralPath $cli -PathType Leaf)){throw 'STATIC_RUNTIME_CLI_PATH_REQUIRED'}
        $cliHash=(Get-FileHash -LiteralPath $cli -Algorithm SHA256).Hash.ToLowerInvariant()
        $ready=Invoke-SetupNative $cli ($prefix+@('info','--format','json')) 20 $Root
        if($ready.ExitCode -ne 0 -and $Start){
            if($p.containerRuntime -eq 'podman'){
                $started=Invoke-SetupNative $cli @('machine','start',$connection.machine.Name) 180 $Root
                if($started.ExitCode -ne 0){throw 'PODMAN_MACHINE_START_FAILED'}
                $connection=Get-CourseStaticPodmanConnection $cli $p.connection $Root
            } else {
                if(-not $paths.Desktop){throw 'DOCKER_DESKTOP_PATH_UNAVAILABLE'}
                Start-Process -FilePath $paths.Desktop -WindowStyle Hidden|Out-Null
                for($attempt=0;$attempt -lt 12;$attempt++){
                    $ready=Invoke-SetupNative $cli ($prefix+@('info','--format','json')) 10 $Root
                    if($ready.ExitCode -eq 0){break};Start-Sleep -Seconds 2
                }
            }
            $ready=Invoke-SetupNative $cli ($prefix+@('info','--format','json')) 20 $Root
        }
        if($ready.ExitCode -ne 0){throw 'LOCAL_ENGINE_UNAVAILABLE_NO_HOST_FALLBACK'}
        $info=$(if($ready.Stdout){$ready.Stdout}else{$ready.Output})|ConvertFrom-Json
        if($p.containerRuntime -eq 'podman'){
            $os=$info.host.os;$arch=$info.host.arch
            if([bool]$info.host.security.rootless -eq [bool]$connection.machine.Rootful){throw 'PODMAN_SSH_ENGINE_ROLE_MISMATCH'}
            $engineIdentity=$info.host.hostname
        } else {$os=$info.OSType;$arch=$info.Architecture;$engineIdentity=$info.ID}
        if($os -ne 'linux' -or $arch -notin @('amd64','x86_64')){throw 'LOCAL_LINUX_AMD64_REQUIRED'}
        $local=Read-CourseJson (Join-Path $Root '.ai-coding/local.json')
        $binding=Get-CourseStaticHash ([ordered]@{
            root=$Root;runtime=$p.containerRuntime;connection=$p.connection;image=$p.image;toolchain=$p.toolchain
            executionRoot=$ExecutionRoot;executionId=$local.executionId;cli=$cli;cliHash=$cliHash
        })
        $engine=Get-CourseStaticHash ([ordered]@{os=$os;arch=$arch;identity=$engineIdentity;connection=$(if($connection){$connection.fingerprint}else{'local-docker-pipe'})})
        $reused=$false;$imageId=$null
        if($PriorContext -and $engineIdentity -and $OperationId -cmatch '^[a-f0-9]{32}$' -and $PriorContext.schemaVersion -eq 1 -and $PriorContext.profile -ceq 'StaticPublish' -and
           $PriorContext.operationId -ceq $OperationId -and $PriorContext.binding -ceq $binding -and $PriorContext.engine -ceq $engine -and
           $PriorContext.imageId -cmatch '^(sha256:)?[a-f0-9]{64}$'){
            $verifiedAt=[DateTimeOffset]::MinValue
            if([DateTimeOffset]::TryParse([string]$PriorContext.verifiedAt,[ref]$verifiedAt)){
                $age=([DateTimeOffset]::UtcNow-$verifiedAt).TotalSeconds
                if($age -ge 0 -and $age -le 900){$imageId=$PriorContext.imageId;$reused=$true}
            }
        }
        if(-not $reused){
            $image=@(Invoke-CourseStaticProbe $cli ($prefix+@('image','inspect',$p.image)) $Root)[0]
            $digest=@($image.RepoDigests|Where-Object {$_ -like ('*@'+$p.toolchain.imageDigest)}).Count -gt 0
            $offline=$p.toolchain.verificationMethod -eq 'archive-sha256+image-config' -and $image.Id -eq $p.toolchain.imageId -and $p.toolchain.archiveSha256 -match '^[a-f0-9]{64}$'
            if($image.Os -ne 'linux' -or $image.Architecture -ne 'amd64' -or (-not $digest -and -not $offline) -or $image.Id -cnotmatch '^(sha256:)?[a-f0-9]{64}$'){throw 'PREPARED_IMAGE_MISMATCH'}
            $imageId=$image.Id
        }
        $cache=[pscustomobject]@{schemaVersion=1;profile='StaticPublish';operationId=$OperationId;binding=$binding;engine=$engine;imageId=$imageId;verifiedAt=$(if($reused){$PriorContext.verifiedAt}else{[DateTimeOffset]::UtcNow.ToString('o')})}
        return [pscustomobject]@{Root=$Root;Project=$p;Cli=$cli;Prefix=$prefix;ImageId=$imageId;Profile='StaticPublish';ContextReused=$reused;RuntimeContext=$cache;CheckedAt=[DateTimeOffset]::UtcNow.ToString('o')}
    } finally {if($lease){Exit-CourseOperation $lease}}
}
